SELECT pp.id AS paper_id, pp.symbol, pp.entry_price, pp.exit_price, MAX(e.price) AS max_price, MIN(e.price) AS min_price, COUNT(e.id) AS n_events, MIN(e.observed_at) AS first_obs, MAX(e.observed_at) AS last_obs FROM crypto_ai.paper_position pp LEFT JOIN crypto_ai.market_price_event e ON e.symbol = pp.symbol AND e.observed_at BETWEEN pp.opened_at AND pp.closed_at WHERE pp.id IN (137,143,158,162,172,182) GROUP BY pp.id, pp.symbol, pp.entry_price, pp.exit_price ORDER BY pp.id LIMIT 10